    48  src_read(pgp_source_t *src, void *buf, size_t len, size_t *readres)
    49  {
    50      size_t              left = len;
    51      size_t              read;
    52      pgp_source_cache_t *cache = src->cache;
    53      bool                readahead = cache ? cache->readahead : false;
    54
    55      if (src->error) {
    56          return false;
    57      }
    58
    59      if (src->eof || (len == 0)) {
    60          *readres = 0;
    61          return true;
    62      }
    63
    64      // Do not read more then available if source size is known
    65      if (src->knownsize && (src->readb + len > src->size)) {
    66          len = src->size - src->readb;
    67          left = len;
    68          readahead = false;
    69      }
    70
    71      // Check whether we have cache and there is data inside
    72      if (cache && (cache->len > cache->pos)) {
    73          read = cache->len - cache->pos;
    74          if (read >= len) {
    75              memcpy(buf, &cache->buf[cache->pos], len);
    76              cache->pos += len;
    77              goto finish;
    78          } else {
    79              memcpy(buf, &cache->buf[cache->pos], read);
    80              cache->pos += read;
    81              buf = (uint8_t *) buf + read;
    82              left = len - read;
    83          }
    84      }
    85
    86      // If we got here then we have empty cache or no cache at all
    87      while (left > 0) {
    88          if (left > sizeof(cache->buf) || !readahead || !cache) {
    89              // If there is no cache or chunk is larger then read directly
    90              if (!src->read(src, buf, left, &read)) {
    91                  src->error = 1;
    92                  return false;
    93              }
    94              if (!read) {
    95                  src->eof = 1;
    96                  len = len - left;
    97                  goto finish;
    98              }
    99              left -= read;
   100              buf = (uint8_t *) buf + read;
   101          } else {
   102              // Try to fill the cache to avoid small reads
   103              if (!src->read(src, &cache->buf[0], sizeof(cache->buf), &read)) {
   104                  src->error = 1;
   105                  return false;
   106              }
   107              if (!read) {
   108                  src->eof = 1;
   109                  len = len - left;
   110                  goto finish;
   111              } else if (read < left) {
   112                  memcpy(buf, &cache->buf[0], read);
